import { useCallback, useState } from 'react';
import { UseProgressTrackerParams } from './useProgressTracker.types';

export function useProgressTracker({ initialStep = 0, stepQuantity }: UseProgressTrackerParams) {
  const [currentStep, setCurrentStep] = useState<number>(initialStep);

  const inRange = useCallback(
    (stepIndex: number) => stepIndex >= 0 && stepIndex < stepQuantity,
    [stepQuantity]
  );

  const goTo = useCallback(
    (stepIndex: number) => {
      if (inRange(stepIndex)) setCurrentStep(stepIndex);
      // eslint-disable-next-line no-console
      else console.warn('The next navigation step index not exist. Insert a valid index.');
    },
    [inRange]
  );

  const goToNext = useCallback(() => {
    goTo(currentStep + 1);
  }, [currentStep, goTo]);

  const goToPrevious = useCallback(() => {
    goTo(currentStep - 1);
  }, [currentStep, goTo]);

  const reset = useCallback(() => {
    goTo(initialStep || 0);
  }, [goTo, initialStep]);

  return {
    currentStep,
    goTo,
    goToNext,
    goToPrevious,
    inRange,
    reset,
  };
}

export default useProgressTracker;
